/**
 * Builds URLs used in QR codes and shareable links.
 *
 * QR code now points directly to a static SVG image file:
 *   <base-url>/cards/{id}.svg
 *
 * When scanned on a phone, the browser opens the SVG as a native image —
 * no website, no JavaScript. The user sees the card and can save it to Photos.
 *
 * The static SVG files are pre-generated by `npm run generate-cards`
 * (or automatically as part of `npm run dev:host` and `npm run build`).
 *
 * Base URL priority:
 *   1. VITE_PUBLIC_URL env var (set before building for production).
 *   2. Current window.location.origin — works automatically when the server
 *      is started with `--host` and the booth is accessed via LAN IP:
 *        npm run dev:host  → open http://192.168.x.x:5173 on the booth
 *        QR   → http://192.168.x.x:5173/cards/display-flex.svg
 *        Phone → opens the card image directly (same WiFi required).
 */
import type { PersonalityId } from '@/types'

const RAW_BASE = import.meta.env.VITE_PUBLIC_URL as string | undefined

function isLocalhostOrigin(): boolean {
  if (typeof window === 'undefined') return false
  const h = window.location.hostname
  return h === 'localhost' || h === '127.0.0.1' || h === '::1' || h === ''
}

function getBase(): string {
  if (RAW_BASE && RAW_BASE.trim() && RAW_BASE !== 'undefined') {
    return RAW_BASE.replace(/\/$/, '')
  }
  if (typeof window !== 'undefined') {
    return window.location.origin
  }
  return ''
}

/**
 * URL that the QR code encodes.
 * Points directly to the pre-generated SVG image file.
 */
export function buildCardImageUrl(id: PersonalityId): string {
  return `${getBase()}/cards/${id}.svg`
}

/**
 * URL for the web card page (used in the "open on this device" fallback link).
 */
export function buildCardPageUrl(id: PersonalityId): string {
  return `${getBase()}/#/card/${id}`
}

/** @deprecated use buildCardImageUrl */
export const buildCardUrl = buildCardImageUrl

/**
 * QR code works when the URL is reachable from another device.
 * Returns false only when the origin is literally localhost/loopback
 * (in which case the phone can't reach the server).
 */
export function isQRUsable(): boolean {
  if (RAW_BASE && RAW_BASE.trim() && RAW_BASE !== 'undefined') {
    return (
      !RAW_BASE.includes('localhost') &&
      !RAW_BASE.includes('127.0.0.1')
    )
  }
  return !isLocalhostOrigin()
}

/** @deprecated renamed to isQRUsable */
export const isPublicUrlConfigured = isQRUsable
